(()=>{const basis='Fixed example: 1 lab · 10 HPLCs · 1 mL/min per HPLC · 16 hours/day · 5 days/week · 48 weeks/year · 80% net fresh and waste reduction · €100/L prepared mobile phase.';function lock(){for(const id of ['view-sustainability','view-procurement']){const p=document.getElementById(id);p.querySelectorAll('.sample-band strong').forEach(e=>e.textContent='1 lab · fixed example over 3 years');p.querySelectorAll('.sample-band small').forEach(e=>e.textContent='10 HPLCs · 45% ACN / 15% methanol / 40% buffer · 80% net reduction · €100/L prepared mobile phase');p.querySelectorAll('[data-model-basis]').forEach(e=>e.textContent=basis);p.querySelectorAll('[data-model-rate]').forEach(e=>e.textContent='80%');}}document.addEventListener('resolve-model',lock);lock();})();